// WF14 triage config. Deterministic ids; MSK timestamps; NO external calls, NO Claude (DEC-130).
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const stamp=moscowStamp();
return [{ json: {
  time_window_days:30,
  max_signals:25,
  region_default:'Москва/МО',
  requested_by:'operator',
  contact_use_policy_default:'manual_review', // with public contact; aggregate_only otherwise — NEVER outreach
  run_stamp:stamp,
  run_id:'wf14_'+stamp,
  agent_request_id:'wf14_req_'+stamp,
  created_at:moscowIsoNow()
}}];

// WF14 CLASSIFY PUBLIC LEAD SIGNALS — deterministic, $0, no Claude (DEC-130).
// Sources: review_queue rows (audience voice routed by WF08) + raw_market_records question/comment rows.
// Only PUBLIC evidence is used. A public profile URL is EVIDENCE, never permission for outreach
// (CONTACT_AND_OUTREACH_POLICY). No private chats, no hidden contacts, no member extraction.
function str(v){return v==null?'':String(v).trim();}
function low(v){return str(v).toLowerCase();}
function cut(s,n){s=str(s);return s.length>n?(s.slice(0,n-1)+'…'):s;}
function hashText(s){s=str(s);let h=5381;for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return ('00000000'+h.toString(16)).slice(-8);}
function rowsOf(name){try{return $(name).all().map(i=>i.json).filter(r=>r&&Object.keys(r).some(k=>str(r[k])!==''));}catch(e){return [];}}
const cfg=$('Set Triage Config').first().json;
const windowDays=Number(cfg.time_window_days)||30;
const cutoffMs=Date.now()-windowDays*86400000;
const maxSignals=Number(cfg.max_signals)||25;
const review=rowsOf('Read review_queue');
const raw=rowsOf('Read raw_market_records');
const existing=rowsOf('Read public_lead_signals');
// dedup vs already-triaged signals: same evidence URL + same text hash never produces a second row
const existingKeys=new Set(existing.map(r=>str(r.post_url)+'::'+(str(r.notes).match(/text_hash=([0-9a-f]{8})/)||[])[1]).filter(Boolean));
// ---- pain vocabulary (DEC-130): keyword -> pain_type enum
const PAIN=[
 ['после отказ','after_refusal'],['отказали','after_refusal'],['отказ банка','after_refusal'],['отказов банк','after_refusal'],
 ['плохая кредитн','bad_credit_history'],['плохой кредитн','bad_credit_history'],['кредитная истори','bad_credit_history'],
 ['просрочк','overdue_debt'],['долг','overdue_debt'],
 ['срочно нужн','urgent_money_need'],['срочно деньги','urgent_money_need'],['горит','urgent_money_need'],
 ['предоплат','prepayment_fear'],
 ['мошенник','fraud_fear'],['обман','fraud_fear'],['кидал','fraud_fear'],['пропада','fraud_fear'],['развод','fraud_fear'],
 ['сколько стоит','broker_price_question'],['сколько это стоит','broker_price_question'],['какая комиссия','broker_price_question'],['процент брокер','broker_price_question'],
 ['ипотек','mortgage_refinance_need'],['рефинансир','mortgage_refinance_need'],['снизить ставк','mortgage_refinance_need'],
 ['для бизнеса','business_finance_need'],['ип и ооо','business_finance_need'],['оборотн','business_finance_need'],['тендерн','business_finance_need']
];
const QUESTION=['подскажите','посоветуйте','кто брал','кто обращался','к кому обращаться','как получить','что делать','?'];
const OBJECTION=['мошенник','обман','кидал','пропада','не верю','развод','боюсь','предоплат'];
const COMPLAINT=['жалоб','обманули','кинули','не вернули','отвратительн'];
const BUY=['нужен кредит','нужен займ','нужна помощь с кредит','к кому обращаться','сколько это стоит','хочу взять','помогите получить','нужен совет — к кому'];
function inWindow(t){const ts=Date.parse(str(t));return !isNaN(ts)&&ts>=cutoffMs;}
// ---- collect candidate items (public comments/questions/reviews focus)
const cands=[];
for(const r of review){
  if(!inWindow(r.created_at))continue;
  if(low(r.route)&&low(r.route)!=='review_queue')continue;
  cands.push({src:'review_queue',source_type:str(r.source_type),platform:low(r.platform),source_url:str(r.source_url),post_url:str(r.source_url),
    profile_url:str(r.profile_url),profile_name:str(r.profile_name),author_handle:'',region:str(r.region),service_need:str(r.service_type)||str(r.detected_need),
    text:[str(r.text_context),str(r.detected_need),str(r.reason)].filter(Boolean).join(' || '),
    contact_public:str(r.contact_public),contact_channel:'',created_at:str(r.created_at),agent_request_id:''});
}
for(const r of raw){
  if(!inWindow(r.created_at))continue;
  const tpt=low(r.touchpoint_type);const rth=low(r.record_type_hint);
  const isAudience=(rth==='question_objection')||['public_comment','forum_discussion','review_source'].indexOf(tpt)>=0;
  if(!isAudience)continue;
  if(low(r.dedup_status).indexOf('duplicate')===0||low(r.dedup_status)==='hard_skipped'||low(r.dedup_status)==='invalid')continue;
  cands.push({src:'raw_market_records',source_type:str(r.source_type),platform:low(r.platform),source_url:str(r.source_url),post_url:str(r.post_url)||str(r.source_url),
    profile_url:str(r.profile_url),profile_name:str(r.profile_name),author_handle:str(r.author_handle),region:str(r.region_hint),service_need:str(r.service_hint)||str(r.probable_need),
    text:[str(r.comment_text),str(r.text_context)].filter(Boolean).join(' || '),
    contact_public:str(r.contact_public),contact_channel:str(r.contact_channel),created_at:str(r.created_at),agent_request_id:str(r.agent_request_id)});
}
// ---- classify
const out=[];const seenBatch=new Set();let considered=0,skipped_dup=0,skipped_irrelevant=0;
for(const c of cands){
  if(out.length>=maxSignals)break;
  considered++;
  const blob=low(c.text);
  if(blob.length<25){skipped_irrelevant++;continue;}
  const pains=[];for(const p of PAIN){if(blob.indexOf(p[0])>=0&&pains.indexOf(p[1])<0)pains.push(p[1]);}
  const qHit=QUESTION.filter(t=>blob.indexOf(t)>=0).length;
  const objHit=OBJECTION.filter(t=>blob.indexOf(t)>=0).length;
  const compHit=COMPLAINT.filter(t=>blob.indexOf(t)>=0).length;
  const buyHit=BUY.filter(t=>blob.indexOf(t)>=0).length;
  if(!pains.length&&!qHit&&!objHit&&!buyHit){skipped_irrelevant++;continue;}
  // intent_type enum: question / objection / complaint / buying_intent / content_signal
  let intent='content_signal';
  if(buyHit&&qHit)intent='buying_intent';
  else if(compHit)intent='complaint';
  else if(objHit&&!qHit)intent='objection';
  else if(qHit)intent='question';
  else if(buyHit)intent='buying_intent';
  // deterministic 0-100 scores
  const urgency=Math.min(100,(blob.indexOf('срочно')>=0?60:0)+(pains.indexOf('urgent_money_need')>=0?30:0)+(buyHit?20:10));
  const intentScore=Math.min(100,buyHit*30+qHit*15+(pains.length?15:0));
  const objScore=Math.min(100,objHit*25+compHit*15);
  const key=str(c.post_url)+'::'+hashText(blob);
  if(existingKeys.has(key)||seenBatch.has(key)){skipped_dup++;continue;}
  seenBatch.add(key);
  const hasContact=!!str(c.contact_public);
  // Sheets formula/#ERROR! fix (DEC-124): leading +/= forced to text
  const safeContact=/^[+=]/.test(str(c.contact_public))?("'"+str(c.contact_public)):str(c.contact_public);
  const painLabel=pains.join(', ')||'unclassified_pain';
  out.push({ json:{
    lead_signal_id:'pls_'+str(cfg.run_stamp)+'_'+(out.length+1),
    created_at:str(cfg.created_at),
    source_type:c.source_type||'unknown',
    platform:c.platform||'unknown',
    source_url:c.source_url,
    post_url:c.post_url,
    profile_url:c.profile_url, // public-only by upstream contract; evidence, NOT outreach permission
    profile_name:c.profile_name,
    author_handle:c.author_handle,
    public_identity_label:(c.profile_name||c.author_handle)?'public_profile_visible':'no_public_identity',
    region:c.region||str(cfg.region_default),
    service_need:c.service_need||'unknown',
    text_evidence:cut(c.text,300),
    pain_type:painLabel,
    intent_type:intent,
    urgency_score:urgency,
    intent_score:intentScore,
    objection_score:objScore,
    contact_public:safeContact,
    contact_channel:str(c.contact_channel),
    contact_use_policy:hasContact?'manual_review':'aggregate_only',
    recommended_action:(intent==='buying_intent'?'manual_review':(intent==='question'?'manual_review':(intent==='objection'||intent==='complaint'?'content_idea':'monitor'))),
    status:'new',
    source_confidence:(c.src==='review_queue'?55:50)+(pains.length>=2?10:0),
    evidence_note:'pains: '+painLabel+'; question_hits='+qHit+'; objection_hits='+objHit+'; buying_hits='+buyHit+'; src='+c.src,
    agent_request_id:str(cfg.agent_request_id),
    run_id:str(cfg.run_id),
    notes:'wf14 deterministic triage (DEC-130); text_hash='+hashText(blob)+'; public evidence only; profile_url is evidence, NOT outreach permission; never auto-outreach.'
  }});
}
if(!out.length){
  return [{ json:{ _no_signals:true, considered:considered, skipped_dup:skipped_dup, skipped_irrelevant:skipped_irrelevant } }];
}
return out;

// One agent_requests row (exactly 21 columns). status=completed. $0, no external calls, no Claude.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Triage Config').first().json;
const items=$('Classify Public Lead Signals').all().map(i=>i.json);
const noSignals=items.length===1&&items[0]._no_signals===true;
const signals=noSignals?[]:items;
const byIntent={};for(const s of signals){const k=str(s.intent_type)||'unknown';byIntent[k]=(byIntent[k]||0)+1;}
const withContact=signals.filter(s=>str(s.contact_public)).length;
return [{ json: {
  agent_request_id:str(cfg.agent_request_id),
  created_at:str(cfg.created_at),
  requested_by:str(cfg.requested_by)||'operator',
  request_type:'public_lead_signal_triage',
  request_text:'Deterministic triage of public audience comments/questions/reviews into public_lead_signals (window '+(Number(cfg.time_window_days)||30)+'d)',
  source_scope:'business_queues',
  platforms:'all',
  query:'review_queue + raw_market_records (question/comment/review rows)',
  region:str(cfg.region_default)||'Москва/МО',
  service_focus:'credit_brokerage',
  requested_limit:Number(cfg.max_signals)||25,
  status:'completed',
  plan_summary:'WF14 Public Lead Signal Triage v0.1 (DEC-130): deterministic keyword classification of PUBLIC evidence into public_lead_signals (28 cols). No Claude, no external calls, no outreach; contact_use_policy=manual_review/aggregate_only.',
  estimated_source_cost_usd:0,
  estimated_analysis_cost_usd:0,
  approval_required:false,
  approved_by:'',
  approved_at:'',
  result_summary:(noSignals?'no_signals; ':'')+'signals_written='+signals.length+'; by_intent='+JSON.stringify(byIntent)+'; with_public_contact='+withContact+'; contact_use_policy=manual_review (with contact) / aggregate_only; outreach=forbidden.',
  next_action:(signals.length?'Manager: review public_lead_signals rows with status=new; confirm/dismiss classification. NO outreach — public profile is evidence, not permission (CONTACT_AND_OUTREACH_POLICY).':'No new public lead signals; run source connectors + WF08 first or widen time_window_days.'),
  notes:'wf14 v0.1 deterministic; reads review_queue + raw_market_records; writes public_lead_signals + agent_requests only; never auto-outreach; no private chats; no member extraction; no hidden contacts.'
}}];

// Final run summary. No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Triage Config').first().json;
const items=$('Classify Public Lead Signals').all().map(i=>i.json);
const noSignals=items.length===1&&items[0]._no_signals===true;
const signals=noSignals?[]:items;
const byIntent={};const byPain={};
for(const s of signals){const k=str(s.intent_type)||'unknown';byIntent[k]=(byIntent[k]||0)+1;
  str(s.pain_type).split(/\s*,\s*/).forEach(p=>{if(p)byPain[p]=(byPain[p]||0)+1;});}
return [{ json: {
  workflow:'14 - Public Lead Signal Triage (Deterministic)',
  run_id:str(cfg.run_id),
  agent_request_id:str(cfg.agent_request_id),
  signals_written:signals.length,
  by_intent:byIntent,
  by_pain:byPain,
  with_public_contact:signals.filter(s=>str(s.contact_public)).length,
  claude_calls:0,
  external_calls:0,
  cost_usd:0,
  next_action:(signals.length?'Manager: review status=new rows in public_lead_signals; confirm/dismiss. NO outreach (CONTACT_AND_OUTREACH_POLICY).':'No new signals; run connectors + WF08 first or widen window.')
}}];
